1: package com.sushihub.notification_service.service;
2: 
3: import org.slf4j.Logger;
4: import org.slf4j.LoggerFactory;
5: import org.springframework.beans.factory.ObjectProvider;
6: import org.springframework.beans.factory.annotation.Value;
7: import org.springframework.mail.SimpleMailMessage;
8: import org.springframework.mail.javamail.JavaMailSender;
9: import org.springframework.scheduling.annotation.Async;
10: import org.springframework.stereotype.Component;
11: 
12: /**
13:  * Реальная отправка писем (канал EMAIL): OTP-коды verification-service, письма о заказе.
14:  *
15:  * <p>Как включить: задать SMTP-сервер окружением —
16:  * {@code SMTP_HOST=smtp.gmail.com}, {@code SMTP_PORT=587}, {@code SMTP_USER}, {@code SMTP_PASSWORD}
17:  * (для Gmail — пароль приложения). Без настройки письма «уходят» только в ленту уведомлений —
18:  * демо-код остаётся в ответе ({@code devCode}), поэтому ничего не ломается.
19:  */
20: @Component
21: public class EmailDispatcher {
22: 
23:     private static final Logger log = LoggerFactory.getLogger(EmailDispatcher.class);
24: 
25:     private final ObjectProvider<JavaMailSender> mailSenderProvider;
26:     private final boolean enabled;
27:     private final String from;
28:     private final String host;
29:     private boolean warned;
30: 
31:     public EmailDispatcher(ObjectProvider<JavaMailSender> mailSenderProvider,
32:                            @Value("${notification.email.enabled:true}") boolean enabled,
33:                            @Value("${notification.email.from:no-reply@sushihub.ru}") String from,
34:                            @Value("${spring.mail.host:}") String host) {
35:         this.mailSenderProvider = mailSenderProvider;
36:         this.enabled = enabled;
37:         this.from = from;
38:         this.host = host;
39:     }
40: 
41:     /**
42:      * Реальная отправка включена: SMTP задан и не выключен явно.
43:      * Используется notification-service, чтобы при живом SMTP скрывать OTP-код
44:      * из ленты уведомлений (код существует только в письме).
45:      */
46:     public boolean isRealSendConfigured() {
47:         return enabled && host != null && !host.isBlank();
48:     }
49: 
50:     /**
51:      * Отправляет письмо. Никогда не бросает исключений наверх: письмо — не повод
52:      * уронить выдачу кода или заказ, всё критичное уже сохранено в БД.
53:      *
54:      * @return true, если письмо реально передано SMTP-серверу (без ошибки).
55:      */
56:     public boolean send(String to, String subject, String body) {
57:         if (!enabled || to == null || to.isBlank()) {
58:             return false;
59:         }
60:         if (host == null || host.isBlank()) {
61:             if (!warned) {
62:                 warned = true;
63:                 log.info("SMTP не настроен (spring.mail.host пуст) — письма не отправляются, "
64:                         + "уведомления остаются в ленте. Настройте SMTP_HOST/SMTP_USER/SMTP_PASSWORD.");
65:             }
66:             log.debug("Письмо не отправлено (SMTP не настроен): {} -> {}", to, subject);
67:             return false;
68:         }
69:         JavaMailSender sender = mailSenderProvider.getIfAvailable();
70:         if (sender == null) {
71:             log.warn("JavaMailSender не доступен, хотя spring.mail.host задан ({}). Письмо не отправлено: {}", host, to);
72:             return false;
73:         }
74:         try {
75:             SimpleMailMessage message = new SimpleMailMessage();
76:             message.setFrom(from);
77:             message.setTo(to);
78:             message.setSubject(subject);
79:             message.setText(body);
80:             sender.send(message);
81:             log.info("Письмо отправлено: {} -> {}", to, subject);
82:             return true;
83:         } catch (Exception e) {
84:             log.warn("Не удалось отправить письмо на {}: {}", to, e.getMessage());
85:             return false;
86:         }
87:     }
88: 
89:     /**
90:      * Асинхронная отправка: SMTP-сессия идёт 1–3 с, а держать на ней HTTP-ответ нельзя —
91:      * шлюз (CircuitBreaker/TimeLimiter, ~1 с) успевает вернуть 503, и фронт уходит в демо
92:      * с выдуманным кодом, который не совпадает с кодом из письма.
93:      *
94:      * <p>Ошибка письма не роняет операцию: код уже сохранён в БД (см. {@link #send}).
95:      */
96:     @Async
97:     public void sendAsync(String to, String subject, String body) {
98:         send(to, subject, body);
99:     }
100: }

