1: package com.sushihub.client;
2: 
3: import org.slf4j.Logger;
4: import org.slf4j.LoggerFactory;
5: import org.springframework.beans.factory.annotation.Value;
6: import org.springframework.stereotype.Component;
7: import org.springframework.web.client.RestTemplate;
8: 
9: import java.util.HashMap;
10: import java.util.Map;
11: 
12: /**
13:  * Отправка уведомлений через notification-service (Eureka + @LoadBalanced RestTemplate).
14:  * Именно здесь код реально «уходит» на почту/телефон: notification-service рендерит шаблон
15:  * VERIFICATION_CODE и, если настроен SMTP, отправляет письмо.
16:  */
17: @Component
18: public class NotificationClient {
19: 
20:     private static final Logger log = LoggerFactory.getLogger(NotificationClient.class);
21: 
22:     private final RestTemplate restTemplate;
23: 
24:     @Value("${notification.service-url:http://notification-service}")
25:     private String notificationServiceUrl;
26: 
27:     public NotificationClient(RestTemplate restTemplate) {
28:         this.restTemplate = restTemplate;
29:     }
30: 
31:     public void sendVerificationCode(Long userId, String target, String channel, String code, int ttlMinutes) {
32:         Map<String, Object> params = new HashMap<>();
33:         params.put("code", code);
34:         params.put("ttlMinutes", String.valueOf(ttlMinutes));
35: 
36:         Map<String, Object> body = new HashMap<>();
37:         body.put("userId", userId);
38:         body.put("recipient", target);
39:         body.put("channel", channel);
40:         body.put("type", "VERIFICATION_CODE");
41:         body.put("params", params);
42: 
43:         try {
44:             restTemplate.postForObject(notificationServiceUrl + "/notifications", body, Object.class);
45:             log.info("Код подтверждения отправлен на {} ({})", target, channel);
46:         } catch (Exception e) {
47:             // Не роняем отправку OTP, если notification-service недоступен:
48:             // код всё равно сохранён, в демо-режиме он вернётся в ответе (devCode).
49:             log.warn("notification-service недоступен ({}), код не доставлен", e.getMessage());
50:         }
51:     }
52: }

