1: package com.sushihub.service;
2: 
3: import com.sushihub.client.NotificationClient;
4: import com.sushihub.dto.ConfirmResponse;
5: import com.sushihub.dto.OtpRequest;
6: import com.sushihub.dto.SendCodeResponse;
7: import com.sushihub.dto.VerifyRequest;
8: import com.sushihub.entity.OtpCode;
9: import com.sushihub.repository.OtpCodeRepository;
10: import org.springframework.beans.factory.annotation.Value;
11: import org.springframework.http.HttpStatus;
12: import org.springframework.stereotype.Service;
13: import org.springframework.web.server.ResponseStatusException;
14: 
15: import java.nio.charset.StandardCharsets;
16: import java.security.MessageDigest;
17: import java.security.SecureRandom;
18: import java.time.Duration;
19: import java.time.LocalDateTime;
20: import java.util.List;
21: import java.util.Locale;
22: import java.util.Set;
23: 
24: /**
25:  * OTP-коды: отправка, кулдаун, срок жизни, лимит попыток и подтверждение.
26:  * Код хранится в виде SHA-256 хэша; в демо-режиме возвращается в ответе (devCode).
27:  */
28: @Service
29: public class VerificationService {
30: 
31:     private static final Set<String> CHANNELS = Set.of("EMAIL", "SMS");
32:     private static final Set<String> PURPOSES = Set.of("REGISTRATION", "LOGIN_2FA", "BIND_CONTACT");
33:     private static final String SENT = "SENT";
34:     private static final String CONFIRMED = "CONFIRMED";
35:     private static final String EXPIRED = "EXPIRED";
36:     private static final String BLOCKED = "BLOCKED";
37: 
38:     private final OtpCodeRepository otpRepository;
39:     private final NotificationClient notifications;
40:     private final SecureRandom random = new SecureRandom();
41: 
42:     @Value("${verification.code-length:6}")
43:     private int codeLength;
44: 
45:     @Value("${verification.ttl-seconds:300}")
46:     private long ttlSeconds;
47: 
48:     @Value("${verification.cooldown-seconds:60}")
49:     private long cooldownSeconds;
50: 
51:     @Value("${verification.max-attempts:5}")
52:     private int maxAttempts;
53: 
54:     // Строгий режим по умолчанию: код НИКОГДА не возвращается в ответе, узнать его можно
55:     // только из реального письма. Демо с devCode включается явно: VERIFICATION_DEV_CODE=true.
56:     @Value("${verification.dev-return-code:false}")
57:     private boolean devReturnCode;
58: 
59:     public VerificationService(OtpCodeRepository otpRepository, NotificationClient notifications) {
60:         this.otpRepository = otpRepository;
61:         this.notifications = notifications;
62:     }
63: 
64:     public SendCodeResponse send(OtpRequest request) {
65:         String channel = normalize(request.channel());
66:         String purpose = normalize(request.purpose());
67:         String target = request.target() == null ? "" : request.target().trim();
68: 
69:         if (target.isEmpty()) {
70:             throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Не указан получатель кода");
71:         }
72:         if (!CHANNELS.contains(channel)) {
73:             throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Канал должен быть EMAIL или SMS");
74:         }
75:         if (!PURPOSES.contains(purpose)) {
76:             throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
77:                     "Назначение должно быть REGISTRATION, LOGIN_2FA или BIND_CONTACT");
78:         }
79: 
80:         LocalDateTime now = LocalDateTime.now();
81:         otpRepository.findTopByTargetAndPurposeOrderByCreatedAtDesc(target, purpose).ifPresent(last -> {
82:             LocalDateTime resendAt = last.getCreatedAt().plusSeconds(cooldownSeconds);
83:             if (now.isBefore(resendAt)) {
84:                 long seconds = Duration.between(now, resendAt).getSeconds() + 1;
85:                 throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
86:                         "Повторно код можно запросить через " + seconds + " с");
87:             }
88:         });
89: 
90:         String code = generateCode();
91:         OtpCode otp = new OtpCode();
92:         otp.setUserId(request.userId());
93:         otp.setChannel(channel);
94:         otp.setTarget(target);
95:         otp.setPurpose(purpose);
96:         otp.setCodeHash(hash(code));
97:         otp.setStatus(SENT);
98:         otp.setAttempts(0);
99:         otp.setExpiresAt(now.plusSeconds(ttlSeconds));
100:         otp.setCreatedAt(now);
101:         OtpCode saved = otpRepository.save(otp);
102: 
103:         notifications.sendVerificationCode(request.userId(), target, channel, code, (int) (ttlSeconds / 60));
104: 
105:         return new SendCodeResponse(
106:                 saved.getId(), target, channel, purpose,
107:                 saved.getExpiresAt(), saved.getCreatedAt().plusSeconds(cooldownSeconds),
108:                 maxAttempts, devReturnCode ? code : null);
109:     }
110: 
111:     public ConfirmResponse confirm(VerifyRequest request) {
112:         if (request.id() == null) {
113:             throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Не указан id кода");
114:         }
115:         OtpCode otp = otpRepository.findById(request.id())
116:                 .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Код не найден — запросите новый"));
117: 
118:         if (CONFIRMED.equals(otp.getStatus())) {
119:             return new ConfirmResponse(otp.getId(), true, otp.getTarget(), otp.getPurpose(), otp.getUserId(), 0);
120:         }
121:         LocalDateTime now = LocalDateTime.now();
122:         if (EXPIRED.equals(otp.getStatus()) || otp.getExpiresAt().isBefore(now)) {
123:             otp.setStatus(EXPIRED);
124:             otpRepository.save(otp);
125:             throw new ResponseStatusException(HttpStatus.GONE, "Код истёк — запросите новый");
126:         }
127:         if (BLOCKED.equals(otp.getStatus()) || otp.getAttempts() >= maxAttempts) {
128:             otp.setStatus(BLOCKED);
129:             otpRepository.save(otp);
130:             throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS, "Слишком много попыток — запросите новый код");
131:         }
132: 
133:         String provided = request.code() == null ? "" : request.code().trim();
134:         if (!otp.getCodeHash().equals(hash(provided))) {
135:             otp.setAttempts(otp.getAttempts() + 1);
136:             if (otp.getAttempts() >= maxAttempts) {
137:                 otp.setStatus(BLOCKED);
138:             }
139:             otpRepository.save(otp);
140:             throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
141:                     "Неверный код. Осталось попыток: " + Math.max(0, maxAttempts - otp.getAttempts()));
142:         }
143: 
144:         otp.setStatus(CONFIRMED);
145:         otp.setConfirmedAt(now);
146:         OtpCode saved = otpRepository.save(otp);
147:         return new ConfirmResponse(saved.getId(), true, saved.getTarget(), saved.getPurpose(),
148:                 saved.getUserId(), Math.max(0, maxAttempts - saved.getAttempts()));
149:     }
150: 
151:     public List<OtpCode> list(String target) {
152:         return target != null && !target.isBlank()
153:                 ? otpRepository.findByTargetContainingOrderByCreatedAtDesc(target)
154:                 : otpRepository.findAllByOrderByCreatedAtDesc();
155:     }
156: 
157:     public OtpCode get(Long id) {
158:         return otpRepository.findById(id)
159:                 .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Код " + id + " не найден"));
160:     }
161: 
162:     private String generateCode() {
163:         StringBuilder sb = new StringBuilder();
164:         for (int i = 0; i < codeLength; i++) {
165:             sb.append(random.nextInt(10));
166:         }
167:         return sb.toString();
168:     }
169: 
170:     private static String normalize(String value) {
171:         return value == null ? "" : value.trim().toUpperCase(Locale.ROOT);
172:     }
173: 
174:     private static String hash(String value) {
175:         try {
176:             MessageDigest digest = MessageDigest.getInstance("SHA-256");
177:             byte[] bytes = digest.digest((value == null ? "" : value).getBytes(StandardCharsets.UTF_8));
178:             StringBuilder sb = new StringBuilder(bytes.length * 2);
179:             for (byte b : bytes) {
180:                 sb.append(Character.forDigit((b >> 4) & 0xF, 16));
181:                 sb.append(Character.forDigit(b & 0xF, 16));
182:             }
183:             return sb.toString();
184:         } catch (Exception e) {
185:             throw new IllegalStateException("SHA-256 недоступен", e);
186:         }
187:     }
188: }

