1: # SushiHub - run all services as separate detached processes (Windows)
2: # Run in background:
3: #   powershell -NoProfile -ExecutionPolicy Bypass -File scripts\run-all.ps1
4: # Logs: SushiHub_Monorepo\logs\<service>.out.log / .err.log
5: 
6: $ErrorActionPreference = 'Stop'
7: $repoRoot = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
8: $java = if ($env:JAVA_HOME -and (Test-Path (Join-Path $env:JAVA_HOME 'bin\java.exe'))) {
9:   Join-Path $env:JAVA_HOME 'bin\java.exe'
10: } else {
11:   (Get-Command java.exe -ErrorAction Stop).Source
12: }
13: $logDir = Join-Path $repoRoot "logs"
14: New-Item -ItemType Directory -Force -Path $logDir | Out-Null
15: 
16: # Shared local settings (database credentials and map keys).
17: $localEnvFile = Join-Path $repoRoot '.env'
18: if (Test-Path $localEnvFile) {
19:   Get-Content $localEnvFile | Where-Object { $_ -match '^\s*[^#][^=]*=' } | ForEach-Object {
20:     $key, $value = $_ -split '=', 2
21:     $key = $key.Trim(); $value = $value.Trim().Trim('"').Trim("'")
22:     if ($key) { Set-Item -Path "Env:$key" -Value $value }
23:   }
24:   Write-Output 'Local settings loaded from .env'
25: }
26: 
27: # SMTP (scripts\smtp.env) — если есть, реальные письма; иначе демо-режим (код в ленте).
28: $smtpFile = Join-Path $repoRoot "scripts\smtp.env"
29: if (Test-Path $smtpFile) {
30:   Get-Content $smtpFile | Where-Object { $_ -match '^\s*[^#][^=]*=' } | ForEach-Object {
31:     $k, $v = $_ -split '=', 2
32:     $k = $k.Trim(); $v = $v.Trim()
33:     if ($k) { Set-Item -Path "Env:$k" -Value $v }
34:   }
35:   Write-Output "SMTP: loaded from scripts/smtp.env (host=$env:SMTP_HOST user=$env:SMTP_USER)"
36: }
37: 
38: $services = @(
39:   "config-server", "eureka-server",
40:   "user-service", "menu-service", "order-service", "payment-service",
41:   "delivery-service", "notification-service", "verification-service",
42:   "recommendation-service", "geo-service", "admin-service",
43:   "analytics-service", "review-service", "support-service",
44:   "api-gateway"
45: )
46: 
47: $ports = @{ 'config-server'=8888; 'eureka-server'=8761; 'api-gateway'=8090;
48:   'user-service'=8081; 'menu-service'=8082; 'order-service'=8083; 'payment-service'=8084;
49:   'delivery-service'=8085; 'notification-service'=8086; 'verification-service'=8087;
50:   'recommendation-service'=8088; 'geo-service'=8089; 'admin-service'=8091;
51:   'analytics-service'=8092; 'review-service'=8093; 'support-service'=8094 }
52: 
53: foreach ($s in $services) {
54:   if (Get-NetTCPConnection -State Listen -LocalPort $ports[$s] -ErrorAction SilentlyContinue) {
55:     Write-Output "SKIP: $s (port $($ports[$s]) already in use)"
56:     continue
57:   }
58:   $dir = Join-Path $repoRoot $s
59:   $jar = Get-ChildItem (Join-Path $dir "target") -Filter "*.jar" -ErrorAction SilentlyContinue |
60:          Where-Object { $_.Name -notmatch 'original|sources|javadoc' } |
61:          Select-Object -First 1
62:   if (-not $jar) { Write-Output "NO JAR: $s"; continue }
63: 
64:   $out = Join-Path $logDir "$s.out.log"
65:   $err = Join-Path $logDir "$s.err.log"
66:   $argStr = '-Xmx512m -Dspring.datasource.hikari.maximum-pool-size=3 -Dmanagement.health.mail.enabled=false -jar "' + $jar.FullName + '"'
67:   # Optional isolated database for a local preview; service HTTP ports stay fixed.
68:   if ($env:SUSHIHUB_DB_PORT -and $s -notin @('config-server', 'eureka-server', 'api-gateway', 'admin-service')) {
69:     $database = $s -replace '-service$', '_db'
70:     $argStr += " --spring.datasource.url=jdbc:postgresql://127.0.0.1:$($env:SUSHIHUB_DB_PORT)/$database"
71:   }
72:   Start-Process -FilePath $java -ArgumentList $argStr -WorkingDirectory $dir -RedirectStandardOutput $out -RedirectStandardError $err -WindowStyle Hidden
73: 
74:   if ($s -in @("config-server", "eureka-server")) { Start-Sleep -Seconds 12 }
75:   else { Start-Sleep -Seconds 3 }
76:   Write-Output "started $s -> $($jar.Name)"
77: }
78: 
79: Write-Output "ALL SERVICES STARTED"
80: Write-Output "Config : http://localhost:8888"
81: Write-Output "Eureka : http://localhost:8761"
82: Write-Output "Gateway: http://localhost:8090"
83: Write-Output "Swagger: http://localhost:8090/swagger-ui.html"
84: 
85: # Keep the launcher alive so detached children are not reaped
86: while ($true) { Start-Sleep -Seconds 60 }

