28:     private final EmailDispatcher emailDispatcher;
29: 
30:     public NotificationService(NotificationRepository repository,
31:                                NotificationProperties properties,
32:                                TemplateRenderer templates,
33:                                EmailDispatcher emailDispatcher) {
34:         this.repository = repository;
35:         this.properties = properties;
36:         this.templates = templates;
37:         this.emailDispatcher = emailDispatcher;
38:     }
39: 
40:     @Transactional(readOnly = true)
41:     public List<Notification> findAll(Long userId, boolean unreadOnly, NotificationType type) {
42:         return repository.search(userId, unreadOnly, type);
43:     }
44: 
45:     @Transactional(readOnly = true)
46:     public Notification findById(Long id) {
47:         return repository.findById(id)
48:                 .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Уведомление " + id + " не найдено"));
49:     }
50: 
51:     @Transactional(readOnly = true)
52:     public long countUnread(Long userId) {
53:         return repository.countByUserIdAndReadFalse(userId);
54:     }
55: 
56:     @Transactional(readOnly = true)
57:     public long countUnreadAdminAlerts() {
58:         return repository.countByTypeAndReadFalse(NotificationType.ADMIN_ALERT);
59:     }
60: 
61:     /**
62:      * «Отправка»: для канала EMAIL при живом SMTP письмо уходит асинхронно
63:      * (см. {@link EmailDispatcher#sendAsync}; ошибка письма не роняет операцию),
64:      * уведомление сохраняется в ленту и пишется в лог.
65:      *
66:      * <p>Безопасность OTP: если SMTP настроен, в ленту и в лог попадает маскированный
67:      * текст без кода — подтвердить можно только реальным кодом из почты.
68:      * В демо-режиме (SMTP не настроен) код остаётся в ленте, иначе проверка была бы невозможна.
69:      */
70:     @Transactional
71:     public Notification send(SendNotificationRequest request) {
72:         Notification n = new Notification();
73:         n.setUserId(request.userId());
74:         n.setRecipient(request.recipient().trim());
75:         n.setChannel(request.channel());
76:         n.setType(request.type());
77:         n.setTitle(isBlank(request.title()) ? templates.title(request.type(), request.params()) : request.title().trim());
78:         n.setMessage(isBlank(request.message()) ? templates.message(request.type(), request.params()) : request.message().trim());
79:         n.setSender(properties.sender());
80:         n.setCreatedAt(Instant.now());
81: 
82:         if (n.getChannel() == NotificationChannel.EMAIL) {
83:             if (emailDispatcher.isRealSendConfigured()) {
84:                 if (n.getType() == NotificationType.VERIFICATION_CODE) {
85:                     // Код реально ушёл письмом — в ленте его не храним (утечка = обход верификации).
86:                     // Письмо отправляем АСИНХРОННО: SMTP-сессия идёт 1–3 с, а держать на ней HTTP-ответ
87:                     // нельзя — шлюз (TimeLimiter ~1 с) вернёт 503, и фронт уйдёт в демо с чужим кодом.
88:                     String body = n.getMessage();
89:                     n.setMessage("Код подтверждения отправлен на вашу почту. "
90:                             + "Введите код из письма, чтобы подтвердить контакт.");
91:                     emailDispatcher.sendAsync(n.getRecipient(), n.getTitle(), body);
92:                 } else {
93:                     emailDispatcher.sendAsync(n.getRecipient(), n.getTitle(), n.getMessage());
94:                 }
95:             } else {
96:                 // SMTP не настроен (демо): письмо не уходит, код остаётся в ленте — иначе не проверить.
97:                 emailDispatcher.send(n.getRecipient(), n.getTitle(), n.getMessage());
98:             }
99:         }
100: 
101:         Notification saved = repository.save(n);
102:         log.info("[{}] {} -> {}: {} | {}", saved.getChannel(), saved.getSender(), saved.getRecipient(), saved.getTitle(), saved.getMessage());
103:         return saved;
104:     }
105: 
106:     @Transactional
107:     public Notification markRead(Long id) {
108:         Notification notification = findById(id);
109:         notification.setRead(true);
110:         return notification;
111:     }
112: 
113:     @Transactional
114:     public int markAllRead(Long userId) {
115:         return repository.markAllReadForUser(userId);
116:     }
117: 
118:     @Transactional
119:     public int markAllAdminAlertsRead() {
120:         return repository.markAllReadForType(NotificationType.ADMIN_ALERT);
121:     }
122: 
123:     @Transactional
124:     public void delete(Long id) {
125:         if (!repository.existsById(id)) {
126:             throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Уведомление " + id + " не найдено");
127:         }
128:         repository.deleteById(id);
129:     }
130: 
131:     private static boolean isBlank(String s) {
132:         return s == null || s.isBlank();
133:     }
134: }

