function addKvmPageTabs() {
  const activePage = location.pathname.split("/").filter(Boolean).slice(-1)[0];

  // Массив с данными для табов
  const tabs = additionalKvmInfo.tabs.map((tab) => {
    const pages = ["vds", "debian", "centos", "ubuntu", "windows"];
    const isActive =
      tab.id === activePage ||
      (tab.id === "classic" && pages.includes(activePage));

    return {
      ...tab,
      active: isActive,
    };
  });

  // Создаем контейнер для табов
  const tabsContainer = document.createElement("div");
  tabsContainer.className = "kvm-tabs-container";

  // Создаем навигационную панель
  const tabsNav = document.createElement("ul");
  tabsNav.className = "kvm-tabs-nav";

  // Создаем элементы табов
  tabs.forEach((tab) => {
    const tabItem = document.createElement("li");
    tabItem.className = `kvm-tab-item ${tab.active ? "active" : ""} ${
      tab.disabled ? "kvm-disabled-tab-item" : ""
    }`;

    const tabLink = document.createElement("a");
    tabLink.className = `kvm-tab-link ${tab.active ? "active" : ""}`;
    tabLink.href = tab.url;
    tabLink.id = `kvm-tab-${tab.id}`;

    if (tab.disabled) {
      tabLink.setAttribute("disabled", "disabled");
      tabLink.href = "#";
    }

    // Создаем div для checkbox
    const checkboxDiv = document.createElement("div");
    checkboxDiv.className = "kvm_checkbox";

    // Если таб активен, добавляем иконку галочки
    if (tab.active) {
      const checkIcon = document.createElement("i");
      checkIcon.className = "fa fa-check";
      checkIcon.setAttribute("aria-hidden", "true");
      checkboxDiv.appendChild(checkIcon);
    }

    // Создаем span для иконки
    const iconSpan = document.createElement("span");
    iconSpan.className = "kvm-tab-item__icon";
    iconSpan.innerHTML = tab.icon;

    // Создаем span для заголовка
    const titleSpan = document.createElement("span");
    titleSpan.textContent = tab.title;

    // Добавляем иконку и заголовок в ссылку
    tabLink.appendChild(checkboxDiv);
    tabLink.appendChild(iconSpan);
    tabLink.appendChild(titleSpan);

    if (tab.id === "high") {
      const tabTooltipElement = document.createElement("span");
      tabTooltipElement.className = "kvm-tab-item__tooltip";
      tabTooltipElement.textContent = "лучший выбор";
      tabItem.appendChild(tabTooltipElement);
    }

    // if (tab.id === "high") {
    //   const tabTooltipElement = document.createElement("span");
    //   tabTooltipElement.className = "kvm-tab-item__tooltip";
    //   tabTooltipElement.textContent = "временно не доступно";
    //   tabItem.appendChild(tabTooltipElement);
    // }

    if (tab.id === "cloud") {
      const tabTooltipElement = document.createElement("span");
      tabTooltipElement.className = "kvm-tab-item__tooltip";
      tabTooltipElement.textContent = "скоро";
      tabItem.appendChild(tabTooltipElement);
    }

    tabItem.appendChild(tabLink);
    tabsNav.appendChild(tabItem);
  });

  // Собираем все вместе
  tabsContainer.appendChild(tabsNav);

  // Возвращаем HTML строку
  return tabsContainer.outerHTML;
}

function chooseKvmOsOptionOnLoad() {
  const activePage = location.pathname.split("/").filter(Boolean).slice(-1)[0];
  // console.log(activePage, activePage.length);
  const pages = ["debian", "centos", "ubuntu", "windows"];

  function capitalize(str) {
    return str.charAt(0).toUpperCase() + str.slice(1);
  }

  if (!pages.includes(activePage)) return;

  $('.kvm-plan_wrapper .kvm-plan_heading[data-name="Profy"]').parent().click();

  if (activePage === "windows") {
    $(`#mineCraft`).click();
    return;
