const rate=1.22*1.17;
function gb(ramGB,cpu,diskGB,months){
  const mem=ramGB*1024; let pv=50*rate;
  if(mem>8192) pv+=((8192/1024*20)+(mem-8192)/1024*80)*rate;
  else if(mem<4096) pv+=((4096/1024*20)+((mem-4096)/1024*10))*rate;
  else pv+=(mem/1024*20)*rate;
  if(cpu===1) pv+=12*rate; else pv+=((cpu-1)*80)*rate;
  if(cpu>4) pv+=(cpu-4)*240*rate;
  if(cpu>6) pv+=(cpu-6)*440*rate;
  if(diskGB>50) pv+=(diskGB*3+(diskGB-50)*3)*rate;
  else if(diskGB<30) pv+=((30*3)+((diskGB-30)*0.5))*rate;
  else pv+=(diskGB*3)*rate;
  const monthly=Math.round(pv);
  const disc=months===1?1:months===3?0.95:months===6?0.93:months===12?0.88:months===24?0.86:1;
  return {cfg:`${ramGB}GB/${cpu}CPU/${diskGB}GB`, monthly, prepay:Math.round(pv*disc), months};
}
