const r=await fetch('https://cloud4box.com/vps/',{headers:{'user-agent':'Mozilla/5.0'}});
const t=await r.text();
const idxs=[];let i=-1;while((i=t.indexOf('470',i+1))>=0&&idxs.length<5)idxs.push(i);
const ctx=idxs.map(i=>t.slice(Math.max(0,i-1500),i+800));
const app=(()=>{const i=t.indexOf('app-vps-calc');return i>=0?t.slice(Math.max(0,i-1000),i+2500):null})();
return {ctx,app};

const r=await fetch('https://cloud4box.com/vps/',{headers:{'user-agent':'Mozilla/5.0'}});
const t=await r.text();
const i=t.indexOf('window.VPSConfigurator =');
const start=t.indexOf('{',i);
// find matching brace
let depth=0,end=-1;
for(let k=start;k<t.length;k++){const ch=t[k];if(ch==='{')depth++;else if(ch==='}'){depth--;if(depth===0){end=k+1;break;}}}
const raw=t.slice(start,end);
let j=null;try{j=JSON.parse(raw)}catch(e){return {error:String(e),raw:raw.slice(0,500)}}
return {keys:Object.keys(j), discounts:j.discounts, tariffs:j.tariffs.map(x=>({id:x.tariff_id,name:x.name,period:x.period,addons:Object.keys(x.addons||{}),base:Object.fromEntries(Object.entries(x).filter(([k])=>/cpu|ram|disk|hdd|location|stock|sold|count/i.test(k)))})).slice(0,20)};

const r=await fetch('https://cloud4box.com/vps/',{headers:{'user-agent':'Mozilla/5.0'}});
const t=await r.text();
const i=t.indexOf('window.VPSConfigurator =');
const start=t.indexOf('{',i);
let depth=0,end=-1;
for(let k=start;k<t.length;k++){const ch=t[k];if(ch==='{')depth++;else if(ch==='}'){depth--;if(depth===0){end=k+1;break;}}}
const j=JSON.parse(t.slice(start,end));
return {init:j.init, locations:j.locations, nets:j.nets, info:j.informations, t0:j.tariffs[0], t1:j.tariffs[1]};

