async function plain(u){
  try{
    const r=await fetch(u,{headers:{'user-agent':'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/131.0 Safari/537.36','accept-language':'ru-RU,ru;q=0.9'},redirect:'follow'});
    let h=await r.text();
    const p=h.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,'\n').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/&laquo;/g,'«').replace(/&raquo;/g,'»').replace(/&mdash;/g,'—').replace(/[ \t]+/g,' ').replace(/\n\s*\n+/g,'\n');
    return {status:r.status,url:r.url,plain:p};
  }catch(e){return{error:String(e)}}
}
const out={};
for(const u of ['https://hostia.net/vds_server.html','https://www.smartape.ru/vps','https://vps.house/']){
  const r=await plain(u);
  if(r.error){out[u]=r;continue;}
  const lines=r.plain.split('\n').map(s=>s.trim()).filter(Boolean);
  const idx=lines.findIndex(l=>/Тариф|тариф|Конфигурац|конфигурац/.test(l));
  out[u]={url:r.url, lines:lines.slice(Math.max(0,idx),idx+160)};
}
return out;

const r=await fetch('https://cloud4box.com/vps/',{headers:{'user-agent':'Mozilla/5.0'}});
const t=await r.text();
const i=t.indexOf('window.VPSConfigurator =');
const start=t.indexOf('{',i);
let depth=0,end=-1;
for(let k=start;k<t.length;k++){const ch=t[k];if(ch==='{')depth++;else if(ch==='}'){depth--;if(depth===0){end=k+1;break;}}}
const j=JSON.parse(t.slice(start,end));
const uniq=[];
const seen=new Set();
for(const x of j.tariffs){
  if(seen.has(x.tariff_id)) continue; seen.add(x.tariff_id);
  uniq.push({id:x.tariff_id,name:x.name,base:x.period['1'],type:x.type,fixed:x.fixed_addons,dc:x.datacenter_id,disk:x.disk_type,net:x.net_key,
    adds:Object.fromEntries(Object.entries(x.addons||{}).map(([k,v])=>[k,{inc:v.include,min:v.min,max:v.max,price:v.period&&v.period['1']}]))});
}
return uniq;

