const r=await fetch('https://timeweb.cloud/services/vds-vps',{headers:{'user-agent':'Mozilla/5.0','accept-language':'ru-RU,ru;q=0.9'}});
const t=await r.text();
const out=[];
for(const needle of ['4 ГБ','4ГБ','4096','2 ГБ','8 ГБ']){
  let i=-1,c=0;
  while((i=t.indexOf(needle,i+1))>=0&&c<3){out.push({needle,ctx:t.slice(Math.max(0,i-500),i+500).replace(/\s+/g,' ')});c++;}
}
return {len:t.length,out:out.slice(0,6)};

const r=await fetch('https://vps.house/js/pages/main.js?v=44.1',{headers:{'user-agent':'Mozilla/5.0'}});
const t=await r.text();
const hits=[];
for(const needle of ['period','Period','дней','дня','сут','30','rent']){
  let i=-1,c=0;
  while((i=t.indexOf(needle,i+1))>=0&&c<3){hits.push({needle,ctx:t.slice(Math.max(0,i-300),i+400).replace(/\s+/g,' ')});c++;}
}
return hits.slice(0,15);

