$word.DisplayAlerts = 0
$res = New-Object System.Collections.Generic.List[string]
try {
    $doc = $word.Documents.Open($docx, $false, $true)
    $h1 = $doc.Styles.Item(-2).NameLocal
    $h2 = $doc.Styles.Item(-3).NameLocal
    $res.Add('PAGES=' + $doc.ComputeStatistics(2) + ' WORDS=' + $doc.ComputeStatistics(0))
    $res.Add('SECTIONS=' + $doc.Sections.Count + ' PARAGRAPHS=' + $doc.Paragraphs.Count + ' TABLES=' + $doc.Tables.Count + ' SHAPES=' + $doc.InlineShapes.Count)
    foreach ($s in $doc.Sections) {
        $ps = $s.PageSetup
        $res.Add(('SECTION {0}: margins T{1} B{2} L{3} R{4} footer=[{5}]' -f $s.Index, [math]::Round($ps.TopMargin,1), [math]::Round($ps.BottomMargin,1), [math]::Round($ps.LeftMargin,1), [math]::Round($ps.RightMargin,1), $s.Footers.Item(1).Range.Text))
    }
