    for ($k = 1; $k -le $doc.InlineShapes.Count; $k++) {
        $sh = $doc.InlineShapes.Item($k)
        $res.Add(('shape {0}: w={1}cm h={2}cm type={3} page={4}' -f $k, [math]::Round($word.PointsToCentimeters($sh.Width),2), [math]::Round($word.PointsToCentimeters($sh.Height),2), $sh.Type, $sh.Range.Information(3)))
    }
    $res.Add('--- TITLE PAGE ---')
    for ($i = 1; $i -le 34; $i++) {
        $t = $doc.Paragraphs.Item($i).Range.Text.Trim()
        if ($t -ne '') { $res.Add(('p{0} page{1}: {2}' -f $i, $doc.Paragraphs.Item($i).Range.Information(3), $t)) }
    }
