    }
    foreach ($p in $paras) {
        if ($p.Style -eq $h1 -or $p.Style -eq $h2 -or $p.Text -eq $tocTitle -or $p.Text.StartsWith('Рисунок')) {
            $res.Add(('page {0} | {1} | {2}' -f $p.Page, $p.Style, $p.Text))
        }
    }
